def solve_n_queens(n, fixed_assignments):
    """
    Solve n-queens problem with fixed assignments.
    fixed_assignments: dict mapping row -> column
    Returns a list where index i is the column of queen in row i, or None if unsatisfiable.
    """
    solution = [None] * n

    # Apply fixed assignments
    for row, col in fixed_assignments.items():
        solution[row] = col

    def is_safe(row, col):
        """Check if placing a queen at (row, col) is safe."""
        for r in range(row):
            c = solution[r]
            if c is None:
                continue
            # Check column
            if c == col:
                return False
            # Check diagonals
            if abs(c - col) == abs(r - row):
                return False
        return True

    def backtrack(row):
        if row == n:
            return True

        # If this row has a fixed assignment, skip to next
        if solution[row] is not None:
            # Verify the fixed assignment is valid
            if not is_safe(row, solution[row]):
                return False
            return backtrack(row + 1)

        # Try each column
        for col in range(n):
            if is_safe(row, col):
                solution[row] = col
                if backtrack(row + 1):
                    return True
                solution[row] = None

        return False

    if backtrack(0):
        return solution
    else:
        return None

# Solve 9-queens with q[3] = 1
result = solve_n_queens(9, {3: 1})
print("Result:", result)

# Verify the solution
if result:
    print("Verifying solution...")
    valid = True
    for i in range(9):
        for j in range(i+1, 9):
            # Check same column
            if result[i] == result[j]:
                print(f"Queens at rows {i} and {j} share column {result[i]}")
                valid = False
            # Check diagonals
            if abs(result[i] - result[j]) == abs(i - j):
                print(f"Queens at rows {i} and {j} are on same diagonal")
                valid = False
    if valid:
        print("Solution is valid!")
    else:
        print("Solution is invalid!")
